    {{
      "name": "string" | null,
      "steps": [
        {{
          "order": int,
          "instruction": "string",
          "timer_minutes": int | null
        }}
      ]
    }}
  ],
  "notes": "string" | null,
  "image_path": null,
  "image_url": null,
  "metadata": {{
    "source": "string" | null,
    "categories": ["string"],
    "cuisine": "string" | null,
    "tags": ["string"]
  }}
}}

foodForms.system:
